/**
 * Minimal re-creation of the CPython exception objects this program can raise,
 * plus the traceback rendering CPython performs for an unhandled exception.
 *
 * Every error carries the dotted name CPython would print before the message
 * (e.g. `schedule.ScheduleValueError`) so the last traceback line matches.
 */

/** Base for anything that models a Python exception. */
export class PyException extends Error {
  /**
   * @param {string} message
   * @param {string} qualname dotted name CPython prints, e.g. "builtins.ValueError"
   */
  constructor(message, qualname) {
    super(message);
    this.name = 'PyException';
    this.pyQualname = qualname;
    /** @type {Array<{file: string, line: number, func: string, source?: string, caret?: string}>} */
    this.pyTraceback = [];
  }
}

export class PyValueError extends PyException {
  constructor(message) {
    super(message, 'ValueError');
    this.name = 'ValueError';
  }
}

export class PyTypeError extends PyException {
  constructor(message) {
    super(message, 'TypeError');
    this.name = 'TypeError';
  }
}

/**
 * Models `SystemExit`. argparse raises this instead of killing the process so
 * the caller can flush streams before the runtime exits.
 */
export class SystemExit extends PyException {
  constructor(code = 0) {
    super(String(code), 'SystemExit');
    this.name = 'SystemExit';
    this.code = code;
  }
}

/**
 * Push a stack frame onto a Python exception, innermost last -- CPython prints
 * frames outermost-first under "most recent call last".
 *
 * @param {PyException} err
 * @param {{file: string, line: number, func: string, source?: string, caret?: string}} frame
 */
export function addFrame(err, frame) {
  err.pyTraceback.unshift(frame);
  return err;
}

/**
 * Render an unhandled Python exception exactly as CPython writes it to stderr,
 * including the trailing newline.
 *
 * @param {PyException} err
 * @returns {string}
 */
export function formatTraceback(err) {
  const lines = ['Traceback (most recent call last):'];
  for (const frame of err.pyTraceback) {
    lines.push(`  File "${frame.file}", line ${frame.line}, in ${frame.func}`);
    // PyInstaller-frozen frames have no source available, so CPython prints
    // only the location line for them.
    if (frame.source !== undefined) lines.push(`    ${frame.source}`);
    if (frame.caret !== undefined) lines.push(`    ${frame.caret}`);
  }
  lines.push(`${err.pyQualname}: ${err.message}`);
  return lines.join('\n') + '\n';
}

