/**
 * Unicode helpers that reproduce Python semantics JavaScript does not share.
 *
 * Python's `re` module matches `\d` against the whole Unicode "Nd" (decimal
 * digit) category, and `int()` accepts those same characters. JavaScript's
 * `\d` is ASCII-only, so a direct transliteration of the source regexes would
 * wrongly reject inputs the original accepts -- verified against the reference
 * build: `--a 1<U+0661>:30` and `--a 10:3<U+0660>` are both valid there.
 */

/** Regex source equivalent to Python's `\d`. Requires the `u` flag. */
export const PY_DIGIT = '\\p{Nd}';

const ND = /\p{Nd}/u;

/** Python's `str.isdigit()`-adjacent test for a single code point. */
function isNd(codePoint) {
  if (codePoint < 0 || codePoint > 0x10ffff) return false;
  return ND.test(String.fromCodePoint(codePoint));
}

/**
 * Numeric value of any Unicode decimal digit.
 *
 * Decimal-digit blocks are contiguous runs of ten code points beginning at the
 * zero digit, and no two runs are adjacent, so walking backwards until the
 * previous code point leaves the category yields the digit's value.
 *
 * @param {string} ch single character
 * @returns {number} 0-9, or -1 when `ch` is not a decimal digit
 */
export function digitValue(ch) {
  const cp = ch.codePointAt(0);
  if (!isNd(cp)) return -1;
  for (let d = 0; d < 10; d += 1) {
    if (!isNd(cp - d - 1)) return d;
  }
  return -1;
}

// Characters Python's int() strips from both ends (str.strip() whitespace).
const PY_WHITESPACE = /^[\s-]*|[\s-]*$/g;

/**
 * `int(str)` for base 10, including Unicode digits, a leading sign and PEP 515
 * underscore separators.
 *
 * @param {string} text
 * @returns {number}
 * @throws {PyValueError} with CPython's message when the string is not a number
 */
export function pyInt(text) {
  const raw = String(text);
  const stripped = raw.replace(PY_WHITESPACE, '');
  let body = stripped;
  let sign = 1;
  if (body.startsWith('+') || body.startsWith('-')) {
    if (body.startsWith('-')) sign = -1;
    body = body.slice(1);
  }

  let value = 0;
  let digits = 0;
  let prevWasUnderscore = true; // leading underscore is invalid
  for (const ch of body) {
    if (ch === '_') {
      if (prevWasUnderscore) return invalidInt(raw);
      prevWasUnderscore = true;
      continue;
    }
    const d = digitValue(ch);
    if (d < 0) return invalidInt(raw);
    value = value * 10 + d;
    digits += 1;
    prevWasUnderscore = false;
  }
  if (digits === 0 || prevWasUnderscore) return invalidInt(raw);
  return sign * value;
}

function invalidInt(raw) {
  // Imported lazily to keep this module free of circular imports at load time.
  throw new (require_PyValueError())(
    `invalid literal for int() with base 10: ${pyRepr(raw)}`
  );
}

// Small indirection so `unicode.mjs` and `exceptions.mjs` stay independent.
let _PyValueError = null;
function require_PyValueError() {
  if (_PyValueError === null) {
    throw new Error('unicode.mjs: call setValueError() during bootstrap');
  }
  return _PyValueError;
}

/** Wire in the ValueError class (called once by `lib/python/index.mjs`). */
export function setValueError(cls) {
  _PyValueError = cls;
}

/**
 * `repr()` for a string: single quotes unless the value contains one.
 * @param {string} s
 */
export function pyRepr(s) {
  const escaped = s
    .replace(/\\/g, '\\\\')
    .replace(/\n/g, '\\n')
    .replace(/\r/g, '\\r')
    .replace(/\t/g, '\\t');
  if (escaped.includes("'") && !escaped.includes('"')) return `"${escaped}"`;
  return `'${escaped.replace(/'/g, "\\'")}'`;
}

