/**
 * The sliver of `datetime.time` that `schedule` relies on: construction with
 * range validation, and `str()` / ISO formatting.
 */

import { PyValueError } from './exceptions.mjs';

const pad = (n, width = 2) => String(n).padStart(width, '0');

export class PyTime {
  /**
   * @param {number} hour 0-23
   * @param {number} minute 0-59
   * @param {number} second 0-59
   * @param {number} microsecond 0-999999
   */
  constructor(hour = 0, minute = 0, second = 0, microsecond = 0) {
    checkRange('hour', hour, 0, 23);
    checkRange('minute', minute, 0, 59);
    checkRange('second', second, 0, 59);
    checkRange('microsecond', microsecond, 0, 999999);
    this.hour = hour;
    this.minute = minute;
    this.second = second;
    this.microsecond = microsecond;
  }

  /** `datetime.time.isoformat()`; microseconds appear only when non-zero. */
  isoformat() {
    const base = `${pad(this.hour)}:${pad(this.minute)}:${pad(this.second)}`;
    return this.microsecond === 0 ? base : `${base}.${pad(this.microsecond, 6)}`;
  }

  /** `str(time)` delegates to isoformat(). */
  toString() {
    return this.isoformat();
  }
}

function checkRange(label, value, low, high) {
  if (!Number.isInteger(value) || value < low || value > high) {
    throw new PyValueError(`${label} must be in ${low}..${high}`);
  }
}

