/**
 * The layout half of `argparse.HelpFormatter`: usage line and option list.
 *
 * Column geometry follows CPython: each entry is indented two spaces, the help
 * column sits at `min(max_invocation_length + 2 + 2, max_help_position)` with
 * `max_help_position` defaulting to 24.
 */

const INDENT = '  ';
const MAX_HELP_POSITION = 24;

/**
 * `--a` with dest `a` and a store action displays as `--a A`.
 * @param {import('./parser.mjs').Action} action
 */
export function formatInvocation(action) {
  if (action.nargs === 0) {
    // Flags such as -h/--help list their option strings alone.
    return action.optionStrings.join(', ');
  }
  const metavar = action.metavar ?? action.dest.toUpperCase();
  return action.optionStrings.map((opt) => `${opt} ${metavar}`).join(', ');
}

/** The bracketed/bare fragment an action contributes to the usage line. */
function formatUsagePart(action) {
  const optionString = action.optionStrings[0];
  const body =
    action.nargs === 0
      ? optionString
      : `${optionString} ${action.metavar ?? action.dest.toUpperCase()}`;
  return action.required ? body : `[${body}]`;
}

/**
 * `usage: PROG [-h] --a A --b B --c C` (no trailing newline).
 *
 * @param {string} prog
 * @param {import('./parser.mjs').Action[]} actions
 */
export function formatUsage(prog, actions) {
  const parts = actions.map(formatUsagePart);
  return `usage: ${[prog, ...parts].join(' ')}`;
}

/**
 * The full `--help` text, terminated by a newline.
 *
 * @param {string} prog
 * @param {import('./parser.mjs').Action[]} actions
 */
export function formatHelp(prog, actions) {
  const invocations = actions.map(formatInvocation);
  const actionMaxLength = Math.max(
    0,
    ...invocations.map((inv) => inv.length + INDENT.length)
  );
  const helpPosition = Math.min(actionMaxLength + 2, MAX_HELP_POSITION);

  const lines = [formatUsage(prog, actions), '', 'options:'];
  actions.forEach((action, i) => {
    const invocation = INDENT + invocations[i];
    if (!action.help) {
      // No help text: CPython emits the invocation with no trailing padding.
      lines.push(invocation);
      return;
    }
    if (invocation.length <= helpPosition - 2) {
      lines.push(invocation.padEnd(helpPosition) + action.help);
    } else {
      // Too wide for the shared column, so the help text drops to its own line.
      lines.push(invocation);
      lines.push(' '.repeat(helpPosition) + action.help);
    }
  });
  return lines.join('\n') + '\n';
}

