/**
 * The `schedule` exception hierarchy.
 *
 * The dotted qualnames matter: an unhandled error prints as
 * `schedule.ScheduleValueError: ...`, which is what the reference build emits.
 */

import { PyException } from '../python/exceptions.mjs';

/** Base class for all schedule errors. */
export class ScheduleError extends PyException {
  constructor(message, qualname = 'schedule.ScheduleError') {
    super(message, qualname);
    this.name = 'ScheduleError';
  }
}

/** Raised when an invalid value is passed to a scheduling call. */
export class ScheduleValueError extends ScheduleError {
  constructor(message) {
    super(message, 'schedule.ScheduleValueError');
    this.name = 'ScheduleValueError';
  }
}

/** Raised when a scheduling combination makes no sense for the interval. */
export class IntervalError extends ScheduleValueError {
  constructor(message) {
    super(message);
    this.pyQualname = 'schedule.IntervalError';
    this.name = 'IntervalError';
  }
}

