/**
 * `schedule.Job` -- the periodic-job builder.
 *
 * Only the construction and validation half is modelled here; that is all the
 * source program exercises (`every().monday.at(...)` followed by `print`).
 */

import { addFrame } from '../python/exceptions.mjs';
import { PyTime } from '../python/datetime.mjs';
import { PY_DIGIT, pyInt, pyRepr } from '../python/unicode.mjs';
import { IntervalError, ScheduleValueError } from './errors.mjs';

/**
 * Line numbers inside the packaged `schedule/__init__.py`, taken from the
 * reference build's own traceback so the rendered traceback matches.
 */
const AT_LINES = { format: 514, hours: 547 };

/**
 * `^[0-2]\d:[0-5]\d(:[0-5]\d)?$` from `Job.at`.
 *
 * Two Python-isms are preserved: `\d` spans the Unicode Nd category (so
 * `1<U+0661>:30` is valid), and `$` also matches before a single trailing
 * newline (so `"10:30\n"` is valid but `"10:30\n\n"` is not).
 */
const DAILY_TIME = new RegExp(
  `^[0-2]${PY_DIGIT}:[0-5]${PY_DIGIT}(:[0-5]${PY_DIGIT})?\\n?$`,
  'u'
);
const HOURLY_TIME = new RegExp(`^([0-5]${PY_DIGIT})?:[0-5]${PY_DIGIT}\\n?$`, 'u');
const MINUTELY_TIME = new RegExp(`^:[0-5]${PY_DIGIT}\\n?$`, 'u');

const WEEKDAYS = [
  'monday',
  'tuesday',
  'wednesday',
  'thursday',
  'friday',
  'saturday',
  'sunday',
];

export class Job {
  /**
   * @param {number} interval how many `unit`s between runs
   * @param {import('./scheduler.mjs').Scheduler|null} scheduler owning scheduler
   */
  constructor(interval, scheduler = null) {
    this.interval = interval;
    this.latest = null;
    this.jobFunc = null;
    this.unit = null;
    this.atTime = null;
    this.lastRun = null;
    this.nextRun = null;
    this.period = null;
    this.startDay = null;
    this.cancelAfter = null;
    this.tags = new Set();
    this.scheduler = scheduler;
  }

  /**
   * `Job.__str__`. With no `do()` attached, `job_func` is None, so Python
   * prints `do=None` alongside the literal `()` and `{}` placeholders.
   */
  toString() {
    const jobFuncName = this.jobFunc === null ? 'None' : this.jobFunc.name;
    const args = this.jobFunc === null ? '()' : formatTuple(this.jobFunc.args);
    const kwargs = this.jobFunc === null ? '{}' : formatDict(this.jobFunc.keywords);
    return (
      `Job(interval=${this.interval}, unit=${this.unit}, do=${jobFuncName}, ` +
      `args=${args}, kwargs=${kwargs})`
    );
  }

  /**
   * Pin a job to a wall-clock time.
   *
   * @param {string} timeStr `HH:MM(:SS)?` for daily/weekday jobs
   * @returns {Job} this, for chaining
   */
  at(timeStr) {
    if (!['days', 'hours', 'minutes'].includes(this.unit) && !this.startDay) {
      throw new ScheduleValueError(
        'Invalid unit (valid units are `days`, `hours`, and `minutes`)'
      );
    }
    if (typeof timeStr !== 'string') {
      const err = new (require_TypeError())('at() should be passed a string');
      throw err;
    }

    if (this.unit === 'days' || this.startDay) {
      if (!DAILY_TIME.test(timeStr)) {
        throw atError(
          'Invalid time format for a daily job (valid format is HH:MM(:SS)?)',
          AT_LINES.format
        );
      }
    }
    if (this.unit === 'hours' && !HOURLY_TIME.test(timeStr)) {
      throw new ScheduleValueError(
        'Invalid time format for an hourly job (valid format is (MM)?:SS)'
      );
    }
    if (this.unit === 'minutes' && !MINUTELY_TIME.test(timeStr)) {
      throw new ScheduleValueError(
        'Invalid time format for a minutely job (valid format is :SS)'
      );
    }

    const parts = timeStr.split(':');
    let hour;
    let minute;
    let second;
    if (parts.length === 3) {
      [hour, minute, second] = parts;
    } else if (parts.length === 2 && this.unit === 'minutes') {
      hour = 0;
      minute = 0;
      second = parts[1];
    } else if (parts.length === 2 && this.unit === 'hours' && parts[0].length) {
      [hour, minute] = parts;
      second = 0;
    } else {
      [hour, minute] = parts;
      second = 0;
    }

    if (this.unit === 'days' || this.startDay) {
      hour = pyInt(hour);
      if (!(hour >= 0 && hour <= 23)) {
        // Reproduced verbatim, including schedule's unformatted `{}`.
        throw atError(
          'Invalid number of hours ({} is not between 0 and 23)',
          AT_LINES.hours
        );
      }
    } else if (this.unit === 'hours') {
      hour = 0;
    } else if (this.unit === 'minutes') {
      hour = 0;
      minute = 0;
    }

    this.atTime = new PyTime(pyInt(hour), pyInt(minute), pyInt(second));
    return this;
  }
}

/** Build a ScheduleValueError already carrying its `schedule` stack frame. */
function atError(message, line) {
  return addFrame(new ScheduleValueError(message), {
    file: 'schedule/__init__.py',
    line,
    func: 'at',
  });
}

// TypeError is only reachable when at() is handed a non-string, which the CLI
// never does; resolved lazily to keep the import list minimal.
function require_TypeError() {
  return globalThis.TypeError;
}

const formatTuple = (values) =>
  values.length === 1 ? `(${pyRepr(values[0])},)` : `(${values.map(pyRepr).join(', ')})`;

const formatDict = (mapping) => {
  const entries = Object.entries(mapping ?? {});
  if (entries.length === 0) return '{}';
  return `{${entries.map(([k, v]) => `${pyRepr(k)}: ${pyRepr(v)}`).join(', ')}}`;
};

// Interval-unit properties: `every().weeks`, `every().days`, ...
for (const unit of ['seconds', 'minutes', 'hours', 'days', 'weeks']) {
  Object.defineProperty(Job.prototype, unit, {
    get() {
      this.unit = unit;
      return this;
    },
  });
  // Singular aliases (`every().week`) require interval == 1 in schedule.
  const singular = unit.slice(0, -1);
  Object.defineProperty(Job.prototype, singular, {
    get() {
      if (this.interval !== 1) {
        throw new IntervalError('Use ' + unit + ' instead of ' + singular);
      }
      return this[unit];
    },
  });
}

// Weekday properties: `every().monday` pins the start day and selects weeks.
for (const day of WEEKDAYS) {
  Object.defineProperty(Job.prototype, day, {
    get() {
      if (this.interval !== 1) {
        throw new IntervalError(
          `Scheduling .${day}() jobs is only allowed for weekly jobs. ` +
            `Using .${day}() on a job scheduled to run every 2 or more weeks ` +
            'is not supported.'
        );
      }
      this.startDay = day;
      return this.weeks;
    },
  });
}

