const HOURLY_TIME = new RegExp(`^([0-5]${PY_DIGIT})?:[0-5]${PY_DIGIT}\\n?$`, 'u');
const MINUTELY_TIME = new RegExp(`^:[0-5]${PY_DIGIT}\\n?$`, 'u');

const WEEKDAYS = [
  'monday',
  'tuesday',
  'wednesday',
  'thursday',
  'friday',
  'saturday',
