/**
 * `schedule.Scheduler` -- the job registry behind the module-level helpers.
 */

import { Job } from './job.mjs';

export class Scheduler {
  constructor() {
    /** @type {Job[]} */
    this.jobs = [];
  }

  /**
   * Start building a job that runs every `interval` units.
   * @param {number} [interval]
   * @returns {Job}
   */
  every(interval = 1) {
    return new Job(interval, this);
  }

  /** Drop every registered job. */
  clear(tag = null) {
    if (tag === null) this.jobs = [];
    else this.jobs = this.jobs.filter((job) => !job.tags.has(tag));
  }

  /** Remove one job from the registry. */
  cancelJob(job) {
    const i = this.jobs.indexOf(job);
    if (i !== -1) this.jobs.splice(i, 1);
  }
}

