/**
 * Numeric value of any Unicode decimal digit.
 *
 * Each decimal-digit set is ten consecutive code points starting at its zero,
 * but distinct sets can sit flush against each other -- the Mathematical
 * Alphanumeric Symbols block chains five of them across U+1D7CE..U+1D7FF. So
 * walk back to the start of the maximal contiguous Nd run, then take the offset
 * modulo ten; run lengths are always multiples of ten and zero-aligned.
 *
 * @param {string} ch single character
 * @returns {number} 0-9, or -1 when `ch` is not a decimal digit
 */
export function digitValue(ch) {
  const cp = ch.codePointAt(0);
  if (!isNd(cp)) return -1;
  let runStart = cp;
  while (isNd(runStart - 1)) runStart -= 1;
  return (cp - runStart) % 10;
}

