/**
 * Unicode helpers that reproduce Python semantics JavaScript does not share.
 *
 * Python's `re` module matches `\d` against the whole Unicode "Nd" (decimal
 * digit) category, and `int()` accepts those same characters. JavaScript's
 * `\d` is ASCII-only, so a direct transliteration of the source regexes would
 * wrongly reject inputs the original accepts -- verified against the reference
 * build: `--a 1<U+0661>:30` and `--a 10:3<U+0660>` are both accepted there,
 * while the No-category `--a 1<U+00B2>:30` is rejected.
 */

import { PyValueError } from './exceptions.mjs';

/** Regex source equivalent to Python's `\d`. Requires the `u` flag. */
export const PY_DIGIT = '\\p{Nd}';

const ND = /\p{Nd}/u;

/** Whether a code point is in Unicode category Nd. */
function isNd(codePoint) {
  if (codePoint < 0 || codePoint > 0x10ffff) return false;
  return ND.test(String.fromCodePoint(codePoint));
}

/**
 * Numeric value of any Unicode decimal digit.
 *
 * Decimal-digit blocks are contiguous runs of ten code points beginning at the
 * zero digit, and no two runs are adjacent, so walking backwards until the
 * previous code point leaves the category yields the digit's value.
 *
 * @param {string} ch single character
 * @returns {number} 0-9, or -1 when `ch` is not a decimal digit
 */
export function digitValue(ch) {
  const cp = ch.codePointAt(0);
  if (!isNd(cp)) return -1;
  for (let d = 0; d < 10; d += 1) {
    if (!isNd(cp - d - 1)) return d;
  }
  return -1;
}

/**
 * `repr()` of a string: single quotes, switching to double quotes when the
 * value contains a single quote but no double quote.
 *
 * @param {string} s
 */
export function pyRepr(s) {
  const escaped = String(s)
    .replace(/\\/g, '\\\\')
    .replace(/\n/g, '\\n')
    .replace(/\r/g, '\\r')
    .replace(/\t/g, '\\t');
  if (escaped.includes("'") && !escaped.includes('"')) return `"${escaped}"`;
  return `'${escaped.replace(/'/g, "\\'")}'`;
}

/**
 * `int(str)` for base 10: surrounding whitespace, an optional sign, Unicode
 * decimal digits and PEP 515 underscore separators.
 *
 * @param {string} text
 * @returns {number}
 * @throws {PyValueError} carrying CPython's message for a bad literal
 */
export function pyInt(text) {
  const raw = String(text);
  let body = raw.trim();

  let sign = 1;
  if (body.startsWith('+') || body.startsWith('-')) {
    if (body.startsWith('-')) sign = -1;
    body = body.slice(1);
  }

  let value = 0;
  let digits = 0;
  let prevWasUnderscore = true; // a leading underscore is invalid
  for (const ch of body) {
    if (ch === '_') {
      if (prevWasUnderscore) return badLiteral(raw);
      prevWasUnderscore = true;
      continue;
    }
    const d = digitValue(ch);
    if (d < 0) return badLiteral(raw);
    value = value * 10 + d;
    digits += 1;
    prevWasUnderscore = false;
  }
  if (digits === 0 || prevWasUnderscore) return badLiteral(raw);
  return sign * value;
}

function badLiteral(raw) {
  throw new PyValueError(
    `invalid literal for int() with base 10: ${pyRepr(raw)}`
  );
}

