/**
 * Render an unhandled Python exception exactly as CPython writes it to stderr,
 * including the trailing newline.
 *
 * @param {PyException} err
 * @returns {string}
 */
export function formatTraceback(err) {
  const lines = ['Traceback (most recent call last):'];
  for (const frame of err.pyTraceback) {
    lines.push(`  File "${frame.file}", line ${frame.line}, in ${frame.func}`);
    // PyInstaller-frozen frames have no source available, so CPython prints
    // only the location line for them.
    if (frame.source !== undefined) lines.push(`    ${frame.source}`);
    if (frame.caret !== undefined) lines.push(`    ${frame.caret}`);
  }
  lines.push(`${err.pyQualname}: ${err.message}`);
  return lines.join('\n') + '\n';
}

