/**
 * Reproduce `linecache.getline`: the traceback's filename is relative, so
 * CPython resolves it against the current working directory and silently
 * renders no source line when the file is not there. That is why the reference
 * build shows the failing statement when run from the directory holding
 * test4.py and omits it from anywhere else.
 *
 * @param {string} file
 * @param {number} lineNumber 1-based
 * @returns {string|null} the raw line, or null when unavailable
 */
function getLine(file, lineNumber) {
  try {
    const text = readFileSync(file, 'utf8');
    return text.split('\n')[lineNumber - 1] ?? null;
  } catch {
    return null;
  }
}

/**
 * Render an unhandled Python exception exactly as CPython writes it to stderr,
 * including the trailing newline.
 *
 * @param {PyException} err
 * @returns {string}
 */
export function formatTraceback(err) {
  const lines = ['Traceback (most recent call last):'];
  for (const frame of err.pyTraceback) {
    lines.push(`  File "${frame.file}", line ${frame.line}, in ${frame.func}`);

    const source = getLine(frame.file, frame.line);
    if (source === null) continue;
    lines.push(`    ${source.trim()}`);
    // The caret span comes from the statement's column offsets; CPython omits
    // it when it would cover the whole line.
    if (frame.caretStart !== undefined && frame.caretLength !== undefined) {
      lines.push(
        `    ${' '.repeat(frame.caretStart)}${'^'.repeat(frame.caretLength)}`
      );
    }
  }
  lines.push(`${err.pyQualname}: ${err.message}`);
  return lines.join('\n') + '\n';
}

