/**
 * Node.js port of dataset/test4.py
 *
 *   import argparse
 *   import schedule
 *
 *   parser = argparse.ArgumentParser()
 *   parser.add_argument('--a', type=str, required=True)
 *   parser.add_argument('--b', type=str, required=True)
 *   parser.add_argument('--c', type=str, required=True)
 *   args = parser.parse_args()
 *
 *   job = schedule.every().monday.at(args.a)  # create a Monday-at-time job
 *   print(job)
 */

import { ArgumentParser } from './lib/argparse/index.mjs';
import * as schedule from './lib/schedule/index.mjs';
import {
  addFrame,
  formatTraceback,
  PyException,
  SystemExit,
} from './lib/python/exceptions.mjs';

/** The source line and caret CPython shows for the failing statement. */
const SOURCE_FRAME = {
  file: 'test4.py',
  line: 10,
  func: '<module>',
  source: 'job = schedule.every().monday.at(args.a)  # 创建每周一特定时间作业',
  caret: `${' '.repeat(6)}${'^'.repeat(34)}`,
};

function main() {
  const parser = new ArgumentParser();
  parser.addArgument('--a', { type: String, required: true });
  parser.addArgument('--b', { type: String, required: true });
  parser.addArgument('--c', { type: String, required: true });
  const args = parser.parseArgs();

  const job = schedule.every().monday.at(args.a); // create a Monday-at-time job
  process.stdout.write(`${job.toString()}\n`);
}

try {
  main();
} catch (err) {
  if (err instanceof SystemExit) {
    // argparse already wrote usage/help to the right stream.
    process.exitCode = err.code;
  } else if (err instanceof PyException) {
    // Unhandled Python exception: traceback on stderr, exit status 1.
    process.stderr.write(formatTraceback(addFrame(err, SOURCE_FRAME)));
    process.exitCode = 1;
  } else {
    throw err;
  }
}

