// Emit fuzz cases for difftest, NUL-separated, on stdout.
// Deterministic LCG so runs are reproducible.
let seed = 1234567;
const rnd = () => ((seed = (seed * 1103515245 + 12345) & 0x7fffffff) / 0x7fffffff);

const alpha = [
  ...'0123456789:. -+_',
  '\n',
  '\t',
  '٠', // Arabic-Indic zero
  '٥',
  '٩',
  '१', // Devanagari one
  '²', // superscript two (category No)
  '１', // fullwidth one
  '\u{1D7D9}', // mathematical double-struck one (astral, Nd)
  'x',
];

const cases = [];
for (let i = 0; i < 600; i += 1) {
  const n = Math.floor(rnd() * 8);
  let t = '';
  for (let j = 0; j < n; j += 1) t += alpha[Math.floor(rnd() * alpha.length)];
  cases.push(t);
}

const p = (n) => String(n).padStart(2, '0');
for (let h = 0; h < 32; h += 1) {
  for (const m of [0, 5, 9, 59, 60]) {
    cases.push(`${p(h)}:${p(m)}`);
    cases.push(`${p(h)}:${p(m)}:${p(m)}`);
  }
}

process.stdout.write(cases.join('�'));

