/**
 * A faithful subset of `argparse.ArgumentParser` covering what this program
 * uses: long options taking exactly one value, `required=True`, the automatic
 * `-h/--help`, and CPython's exact error text and exit codes.
 *
 * Behaviours reproduced deliberately, each verified against the reference
 * build (see the notes on `parseOptional` and `parseArgs`):
 *   - `--a=VALUE` inline values and prefix abbreviation (`--h` -> `--help`)
 *   - the negative-number heuristic, so `--a -5` takes `-5` as a value
 *     while `--a -5:30` reports a missing argument
 *   - a bare `-`, and any token containing a space, count as values
 *   - the first `--` turns every later token into a non-option, and the `--`
 *     itself survives into the unrecognised-arguments list
 *   - missing-required is reported before unrecognised-arguments
 */

import { SystemExit } from '../python/exceptions.mjs';
import { PY_DIGIT } from '../python/unicode.mjs';
import { formatHelp, formatUsage } from './formatter.mjs';

const PREFIX_CHARS = '-';

// argparse's `_negative_number_matcher`. Python's \d is Unicode-aware, so a
// token like `-<U+0661>` is treated as a value rather than an option.
const NEGATIVE_NUMBER = new RegExp(
  `^-${PY_DIGIT}+$|^-${PY_DIGIT}*\\.${PY_DIGIT}+$`,
  'u'
);

/** One `add_argument()` registration. */
export class Action {
  constructor({ optionStrings, dest, required, help, nargs, metavar, type }) {
    this.optionStrings = optionStrings;
    this.dest = dest;
    this.required = required ?? false;
    this.help = help ?? '';
    this.nargs = nargs ?? 1; // 0 for flags, 1 for single-value store actions
    this.metavar = metavar ?? null;
    this.type = type ?? String;
  }
}

export class ArgumentParser {
  /** @param {{prog?: string}} [options] */
  constructor(options = {}) {
    // argparse defaults prog to os.path.basename(sys.argv[0]).
    this.prog = options.prog ?? defaultProg();
    /** @type {Action[]} */
    this.actions = [];
    /** @type {Map<string, Action>} */
    this.optionStringActions = new Map();

    this.addArgument(['-h', '--help'], {
      dest: 'help',
      nargs: 0,
      help: 'show this help message and exit',
    });
  }

  /**
   * @param {string|string[]} optionStrings
   * @param {{dest?: string, required?: boolean, help?: string, nargs?: number,
   *          metavar?: string, type?: Function}} [config]
   */
  addArgument(optionStrings, config = {}) {
    const opts = Array.isArray(optionStrings) ? optionStrings : [optionStrings];
    // argparse derives dest from the first long option, minus its prefix.
    const dest =
      config.dest ??
      (opts.find((o) => o.startsWith('--')) ?? opts[0])
        .replace(/^-+/, '')
        .replace(/-/g, '_');

    const action = new Action({ ...config, optionStrings: opts, dest });
    this.actions.push(action);
    for (const opt of opts) this.optionStringActions.set(opt, action);
    return action;
  }

  formatUsage() {
    return formatUsage(this.prog, this.actions);
  }

  formatHelp() {
    return formatHelp(this.prog, this.actions);
  }

  /** `parser.exit()`: raise SystemExit so the caller can flush and unwind. */
  exit(status = 0, message = '') {
    if (message) process.stderr.write(message);
    throw new SystemExit(status);
  }

  /** `parser.error()`: usage + message on stderr, exit status 2. */
  error(message) {
    process.stderr.write(`${this.formatUsage()}\n`);
    process.stderr.write(`${this.prog}: error: ${message}\n`);
    throw new SystemExit(2);
  }

  /**
   * Classify a token, mirroring `ArgumentParser._parse_optional`.
   *
   * @param {string} argString
   * @returns {null | [Action|null, string, string|null]} null when the token is
   *   a value; otherwise [action-or-null, option string, inline value].
   */
  parseOptional(argString) {
    if (argString === '') return null;
    if (!PREFIX_CHARS.includes(argString[0])) return null;

    const exact = this.optionStringActions.get(argString);
    if (exact) return [exact, argString, null];

    // A lone "-" is a value, not an option.
    if (argString.length === 1) return null;

    if (argString.includes('=')) {
      const eq = argString.indexOf('=');
      const optionString = argString.slice(0, eq);
      const explicitArg = argString.slice(eq + 1);
      const action = this.optionStringActions.get(optionString);
      if (action) return [action, optionString, explicitArg];
    }

    const tuples = this.getOptionTuples(argString);
    if (tuples.length > 1) {
      const names = tuples.map((t) => t[1]).join(', ');
      this.error(`ambiguous option: ${argString} could match ${names}`);
    }
    if (tuples.length === 1) return tuples[0];

    if (NEGATIVE_NUMBER.test(argString)) {
      // No registered option looks like a negative number, so this is a value.
      return null;
    }
    if (argString.includes(' ')) return null;

    // Option-shaped but unknown: argparse defers it to the extras list.
    return [null, argString, null];
  }

  /** Prefix-abbreviation lookup, mirroring `_get_option_tuples`. */
  getOptionTuples(optionString) {
    const result = [];
    const isLong =
      PREFIX_CHARS.includes(optionString[0]) &&
      PREFIX_CHARS.includes(optionString[1]);

    if (isLong) {
      let prefix = optionString;
      let explicitArg = null;
      if (optionString.includes('=')) {
        const eq = optionString.indexOf('=');
        prefix = optionString.slice(0, eq);
        explicitArg = optionString.slice(eq + 1);
      }
      for (const [candidate, action] of this.optionStringActions) {
        if (candidate.startsWith(prefix)) result.push([action, candidate, explicitArg]);
      }
      return result;
    }

    // Single-dash: try "-xVALUE" and "-x=VALUE" shapes.
    const shortPrefix = optionString.slice(0, 2);
    const shortExplicit = optionString.slice(2);
    for (const [candidate, action] of this.optionStringActions) {
      if (candidate === shortPrefix) {
        result.push([action, candidate, shortExplicit]);
      } else if (candidate.startsWith(optionString)) {
        result.push([action, candidate, null]);
      }
    }
    return result;
  }

  /**
   * @param {string[]} [argv] defaults to the real command line
   * @returns {Record<string, string>} the populated namespace
   */
  parseArgs(argv) {
    const args = argv ?? process.argv.slice(2);
    /** @type {Record<string, string|undefined>} */
    const namespace = {};
    for (const action of this.actions) {
      if (action.dest !== 'help') namespace[action.dest] = undefined;
    }

    const extras = [];
    const seen = new Set();
    let literalMode = false; // set by the first "--"

    for (let i = 0; i < args.length; i += 1) {
      const arg = args[i];

      if (literalMode) {
        extras.push(arg);
        continue;
      }
      if (arg === '--') {
        // argparse marks the separator, then treats the rest as non-options.
        // With no positionals declared, the separator itself becomes an extra.
        literalMode = true;
        extras.push(arg);
        continue;
      }

      const parsed = this.parseOptional(arg);
      if (parsed === null) {
        extras.push(arg);
        continue;
      }

      const [action, optionString, explicitArg] = parsed;
      if (action === null) {
        extras.push(arg);
        continue;
      }

      if (action.nargs === 0) {
        if (explicitArg !== null) {
          this.error(`argument ${action.optionStrings.join('/')}: ignored explicit argument ${explicitArg}`);
        }
        if (action.dest === 'help') {
          process.stdout.write(this.formatHelp());
          throw new SystemExit(0);
        }
        seen.add(action);
        continue;
      }

      let value;
      if (explicitArg !== null) {
        value = explicitArg;
      } else {
        const next = i + 1 < args.length ? args[i + 1] : null;
        // "--" is recognised before value assignment, so it never becomes a value.
        const nextIsValue =
          next !== null && next !== '--' && this.parseOptional(next) === null;
        if (!nextIsValue) {
          this.error(
            `argument ${action.optionStrings.join('/')}: expected one argument`
          );
        }
        value = next;
        i += 1;
      }

      namespace[action.dest] = action.type(value);
      seen.add(action);
    }

    // argparse checks required arguments before reporting unrecognised ones.
    const missing = this.actions
      .filter((a) => a.required && !seen.has(a))
      .map((a) => a.optionStrings.join('/'));
    if (missing.length > 0) {
      this.error(
        `the following arguments are required: ${missing.join(', ')}`
      );
    }
    if (extras.length > 0) {
      this.error(`unrecognized arguments: ${extras.join(' ')}`);
    }

    return namespace;
  }
}

function defaultProg() {
  const entry = process.argv[1];
  if (!entry) return '';
  const parts = entry.split(/[/\\]/);
  return parts[parts.length - 1];
}

