// Emit fuzz argv vectors for fuzz_argv.sh: one vector per line, each token
// base64-encoded and space-separated so spaces/newlines/NULs survive the shell.
let seed = 987654321;
const rnd = () => ((seed = (seed * 1103515245 + 12345) & 0x7fffffff) / 0x7fffffff);

// Tokens chosen to probe option recognition, abbreviation, the negative-number
// heuristic, inline '=' values, packed short options and the '--' separator.
const tokens = [
  '--a', '--b', '--c', '--a=10:30', '--b=x', '--c=y', '--a=', '-a', '-h',
  '--h', '--he', '--help', '--help=x', '--ab', '--', '-', '-5', '-1.5', '-.5',
  '-0', '-1e3', '-5:30', '- 5', '-x y', '-hxx', '-h-a', '-h=x', '-hh',
  '10:30', '24:00', 'abc', '', 'x', 'y',
];

const vectors = [];
for (let i = 0; i < 700; i += 1) {
  const n = Math.floor(rnd() * 6);
  const argv = [];
  for (let j = 0; j < n; j += 1) argv.push(tokens[Math.floor(rnd() * tokens.length)]);
  vectors.push(argv);
}

const encode = (v) => v.map((t) => Buffer.from(t, 'utf8').toString('base64')).join(' ');
process.stdout.write(vectors.map(encode).join('\n') + '\n');

