// Emit fuzz argv vectors for fuzz_argv.sh: records NUL-separated within a
// vector, and 0x1e-separated between vectors.
let seed = 987654321;
const rnd = () => ((seed = (seed * 1103515245 + 12345) & 0x7fffffff) / 0x7fffffff);

// Tokens chosen to probe option recognition, abbreviation, the negative-number
// heuristic, inline '=' values and the '--' separator.
const tokens = [
  '--a', '--b', '--c', '--a=10:30', '--b=x', '--c=y', '--a=', '-a', '-h',
  '--h', '--he', '--help', '--ab', '--', '-', '-5', '-1.5', '-.5', '-0',
  '-1e3', '-5:30', '- 5', '-x y', '10:30', '24:00', 'abc', '', 'x', 'y',
];

const vectors = [];
for (let i = 0; i < 500; i += 1) {
  const n = Math.floor(rnd() * 6);
  const argv = [];
  for (let j = 0; j < n; j += 1) argv.push(tokens[Math.floor(rnd() * tokens.length)]);
  vectors.push(argv);
}

const NUL = String.fromCharCode(0);
const RS = String.fromCharCode(30);
process.stdout.write(vectors.map((v) => v.join(NUL)).join(RS));

